def merge(intervals: list[list[int]]) -> list[list[int]]:
    if not intervals:
        return []

    # Create new normalized intervals without modifying the original input
    normalized = [[min(i), max(i)] for i in intervals]
    normalized.sort(key=lambda x: x[0])

    merged = [normalized[0]]
    for start, end in normalized[1:]:
        if start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])

    return merged
