import heapq

def cheapest_route(flights, src, dst, max_stops):
    if src == dst:
        return (0, [src])

    adj = {}
    for o, d, p in flights:
        adj.setdefault(o, []).append((d, p))

    # PQ stores: (total_price, num_flights, airports_tuple, current_airport)
    pq = [(0, 0, (src,), src)]
    best = {src: (0, 0, (src,))}

    while pq:
        cost, hops, path, u = heapq.heappop(pq)

        # Skip stale entries that have been superseded by a better route to the same airport
        if u in best and (cost, hops, path) != best[u]:
            continue

        if u == dst:
            return (cost, list(path))

        # max_stops intermediate airports => at most max_stops + 1 flights total
        if hops >= max_stops + 1:
            continue

        for v, price in adj.get(u, []):
            new_cost = cost + price
            new_hops = hops + 1
            new_path = path + (v,)

            curr_best = best.get(v)
            # Update if we found a strictly better route (cheaper, or same price/fewer flights/lex smaller)
            if curr_best is None or (new_cost, new_hops, new_path) < curr_best:
                best[v] = (new_cost, new_hops, new_path)
                heapq.heappush(pq, (new_cost, new_hops, new_path, v))

    return None
