def evaluate(expr: str):
    tokens = []
    i, n = 0, len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
        elif c.isdigit() or c == '.':
            start = i
            has_dot = False
            if c == '.':
                i += 1
                if i >= n or not expr[i].isdigit():
                    raise ValueError("Malformed number")
            while i < n and (expr[i].isdigit() or (expr[i] == '.' and not has_dot)):
                if expr[i] == '.':
                    has_dot = True
                i += 1
            num_str = expr[start:i]
            tokens.append(('NUM', float(num_str) if '.' in num_str else int(num_str)))
        elif expr[i:i+2] in ('//', '**'):
            tokens.append(('OP', expr[i:i+2]))
            i += 2
        elif c in '+-*/%()':
            tokens.append(('OP', c))
            i += 1
        else:
            raise ValueError("Unknown character")

    if not tokens:
        raise ValueError("Empty expression")

    pos = 0
    length = len(tokens)

    def peek():
        return tokens[pos] if pos < length else (None, None)

    def consume(expected_type=None):
        nonlocal pos
        tok = peek()
        if tok[0] is None:
            raise ValueError("Unexpected end of input")
        if expected_type and tok[0] != expected_type:
            raise ValueError(f"Expected {expected_type}")
        pos += 1
        return tok

    def parse_expr():
        left = parse_term()
        while peek()[0] == 'OP' and peek()[1] in ('+', '-'):
            op = consume()[1]
            right = parse_term()
            if op == '+': left += right
            else: left -= right
        return left

    def parse_term():
        left = parse_unary()
        while peek()[0] == 'OP' and peek()[1] in ('*', '/', '//', '%'):
            op = consume()[1]
            right = parse_unary()
            if op == '*': left *= right
            elif op == '/': left = left / right
            elif op == '//': left = left // right
            elif op == '%': left = left % right
        return left

    def parse_unary():
        if peek()[0] == 'OP' and peek()[1] in ('+', '-'):
            op = consume()[1]
            val = parse_power()
            return -val if op == '-' else val
        return parse_power()

    def parse_power():
        base = parse_atom()
        if peek()[0] == 'OP' and peek()[1] == '**':
            consume()
            exp = parse_unary()
            return base ** exp
        return base

    def parse_atom():
        tok = peek()
        if tok[0] == 'NUM':
            consume()
            return tok[1]
        elif tok[0] == 'OP' and tok[1] == '(':
            consume()
            val = parse_expr()
            if not (peek()[0] == 'OP' and peek()[1] == ')'):
                raise ValueError("Unbalanced parentheses")
            consume()
            return val
        else:
            raise ValueError("Invalid expression syntax")

    result = parse_expr()
    if pos != length:
        raise ValueError("Unexpected tokens")
    return result
