from collections import OrderedDict
import time

class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock=time.monotonic):
        if capacity < 1 or ttl <= 0:
            raise ValueError("capacity must be >= 1 and ttl > 0")
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self._cache = OrderedDict()  # key -> [expiry, value]
        self._size = 0

    def _is_expired(self, expiry):
        return self.clock() >= expiry

    def _make_room(self):
        # Clean up expired entries and evict the LRU live entry if needed.
        for key in list(self._cache):
            expiry, _ = self._cache[key]
            if self._is_expired(expiry):
                del self._cache[key]
                self._size -= 1
            else:
                # First live entry found is the LRU one. Evict it to make space.
                del self._cache[key]
                self._size -= 1
                return

    def set(self, key, value):
        now = self.clock()
        expiry = now + self.ttl

        if key in self._cache:
            old_expiry, _ = self._cache[key]
            if not self._is_expired(old_expiry):
                # Existing live entry: update expiry and move to MRU
                self._cache[key][0] = expiry
                self._cache.move_to_end(key)
                return
            else:
                # Expired entry: remove it first
                del self._cache[key]
                self._size -= 1

        if self._size == self.capacity:
            self._make_room()

        self._cache[key] = [expiry, value]
        self._cache.move_to_end(key)
        self._size += 1

    def get(self, key, default=None):
        if key not in self._cache:
            return default
        expiry, value = self._cache[key]
        if self._is_expired(expiry):
            del self._cache[key]
            self._size -= 1
            return default
        # Live: move to MRU, do NOT extend expiry
        self._cache.move_to_end(key)
        return value

    def delete(self, key) -> bool:
        if key not in self._cache:
            return False
        expiry, _ = self._cache[key]
        if self._is_expired(expiry):
            del self._cache[key]
            self._size -= 1
            return False
        del self._cache[key]
        self._size -= 1
        return True

    def __len__(self):
        return self._size

    def __contains__(self, key) -> bool:
        if key not in self._cache:
            return False
        expiry, _ = self._cache[key]
        # Check liveness without altering recency
        return not self._is_expired(expiry)
