import re

def expand_ranges(s: str) -> list[int]:
    s = s.strip()
    if not s:
        return []
    nums = []
    range_pat = re.compile(r'^(-?\d+)-(-?\d+)$')
    int_pat = re.compile(r'^-?\d+$')

    for item in s.split(','):
        item = item.strip()
        if not item:
            raise ValueError("Empty item")
        m = range_pat.match(item)
        if m:
            a, b = int(m.group(1)), int(m.group(2))
            if a > b:
                raise ValueError(f"Invalid range: {a}-{b}")
            nums.extend(range(a, b + 1))
        elif int_pat.match(item):
            nums.append(int(item))
        else:
            raise ValueError(f"Malformed item: '{item}'")
    return sorted(set(nums))

def compress_ranges(nums) -> str:
    sorted_nums = sorted(set(nums))
    if not sorted_nums:
        return ""
    res = []
    start = prev = sorted_nums[0]
    for num in sorted_nums[1:]:
        if num == prev + 1:
            prev = num
        else:
            if prev - start >= 2:
                res.append(f"{start}-{prev}")
            else:
                res.extend(map(str, range(start, prev + 1)))
            start = prev = num
    if prev - start >= 2:
        res.append(f"{start}-{prev}")
    else:
        res.extend(map(str, range(start, prev + 1)))
    return ",".join(res)
