import sys

def cheapest_route(flights, src, dst, max_stops):
    if src == dst:
        return (0, [src])

    adj = {}
    for u, v, p in flights:
        adj.setdefault(u, []).append((v, p))

    # Sort neighbors by price ascending, then airport name ascending
    for u in adj:
        adj[u].sort(key=lambda x: (x[1], x[0]))

    best = None  # Will store (price, num_flights, path_list)
    path = [src]
    visited = {src}
    sys.setrecursionlimit(5000)

    def dfs(u, current_price):
        nonlocal best
        if u == dst:
            num_flights = len(path) - 1
            candidate = (current_price, num_flights, path[:])
            if best is None or candidate < best:
                best = candidate
            return

        # Max allowed flights is max_stops + 1. 
        # Number of airports visited = number of flights + 1.
        if len(path) > max_stops + 1:
            return

        for v, p in adj.get(u, []):
            if v not in visited:
                new_price = current_price + p
                # Prune branches that already exceed the best known price
                if best is not None and new_price > best[0]:
                    continue
                visited.add(v)
                path.append(v)
                dfs(v, new_price)
                path.pop()
                visited.remove(v)

    dfs(src, 0)

    return (best[0], best[2]) if best else None
