from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        if ttl <= 0:
            raise ValueError("ttl must be > 0")
        self._capacity = capacity
        self._ttl = ttl
        self._clock = clock
        self._data = OrderedDict()
        self._live_count = 0

    def _now(self) -> float:
        return self._clock()

    def _evict(self, now: float):
        # Evict LRU entries until space is available for a new live entry.
        # Expired entries are removed as a side effect (amortized cleanup).
        while self._live_count >= self._capacity and self._data:
            key, (val, expiry) = self._data.popitem(last=False)
            if now < expiry:
                self._live_count -= 1
                return
            self._live_count -= 1

    def get(self, key, default=None):
        now = self._now()
        if key in self._data:
            val, expiry = self._data[key]
            if now >= expiry:
                del self._data[key]
                self._live_count -= 1
                return default
            self._data.move_to_end(key)
            return val
        return default

    def set(self, key, value):
        now = self._now()
        if key in self._data:
            val, expiry = self._data[key]
            if now >= expiry:
                # Treat expired entry as missing
                del self._data[key]
                self._live_count -= 1
            else:
                # Update live entry: restart TTL, mark MRU
                self._data.move_to_end(key)
                self._data[key] = (value, now + self._ttl)
                return

        # New or re-activated key: ensure capacity
        if self._live_count >= self._capacity:
            self._evict(now)
        self._data[key] = (value, now + self._ttl)
        self._live_count += 1

    def delete(self, key) -> bool:
        now = self._now()
        if key in self._data:
            val, expiry = self._data[key]
            if now >= expiry:
                # Already logically gone; just clean up storage
                del self._data[key]
                self._live_count -= 1
                return False
            del self._data[key]
            self._live_count -= 1
            return True
        return False

    def __len__(self) -> int:
        return self._live_count

    def __contains__(self, key) -> bool:
        if key not in self._data:
            return False
        _, expiry = self._data[key]
        return self._now() < expiry
