import heapq

def build_order(deps: dict[str, list[str]]) -> list[str]:
    # Collect all unique targets (both keys and dependency values)
    nodes = set()
    for k, vs in deps.items():
        nodes.add(k)
        nodes.update(vs)

    adj = {n: [] for n in nodes}
    in_degree = {n: 0 for n in nodes}

    # Build graph: dep -> target (since target depends on dep)
    for target, dependencies in deps.items():
        seen = set()
        for dep in dependencies:
            if dep not in seen:
                adj[dep].append(target)
                in_degree[target] += 1
                seen.add(dep)

    # Initialize min-heap with targets that have no dependencies
    heap = [n for n in nodes if in_degree[n] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(heap, v)

    # If not all nodes were processed, a cycle exists
    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result
